create table if not exists public.event_settings(id integer primary key default 1 check(id=1),locked boolean not null default false);
insert into public.event_settings(id,locked) values(1,false) on conflict(id) do nothing;
create table if not exists public.wines(wine_no integer primary key check(wine_no between 1 and 3),country text not null default '',price integer not null default 0 check(price>=0),taste text not null default '');
insert into public.wines(wine_no) values(1),(2),(3) on conflict(wine_no) do nothing;
create table if not exists public.participants(name text primary key check(name in ('Pelle','Sanna','Nordborg','Katta','Fredrik','Anna','Johan','Karin')),guesses jsonb not null,favorite integer not null check(favorite between 1 and 3),updated_at timestamptz not null default now());
alter table public.event_settings enable row level security; alter table public.wines enable row level security; alter table public.participants enable row level security;
drop policy if exists event_read on public.event_settings; create policy event_read on public.event_settings for select to anon,authenticated using(true);
drop policy if exists participants_insert on public.participants; create policy participants_insert on public.participants for insert to anon,authenticated with check(true);
drop policy if exists participants_update on public.participants; create policy participants_update on public.participants for update to anon,authenticated using(true) with check(true);
drop policy if exists participants_admin_read on public.participants; create policy participants_admin_read on public.participants for select to authenticated using(true);
drop policy if exists participants_admin_delete on public.participants; create policy participants_admin_delete on public.participants for delete to authenticated using(true);
drop policy if exists wines_admin_read on public.wines; create policy wines_admin_read on public.wines for select to authenticated using(true);
drop policy if exists wines_admin_update on public.wines; create policy wines_admin_update on public.wines for update to authenticated using(true) with check(true);
drop policy if exists event_admin_update on public.event_settings; create policy event_admin_update on public.event_settings for update to authenticated using(true) with check(true);
create or replace function public.get_results() returns jsonb language plpgsql security definer set search_path=public as $$ declare l boolean; r jsonb; begin select locked into l from event_settings where id=1; if not l and auth.role()<>'authenticated' then raise exception 'Resultatet är inte publicerat ännu.'; end if; select jsonb_build_object('wines',coalesce((select jsonb_agg(jsonb_build_object('wine_no',wine_no,'country',country,'price',price,'taste',taste) order by wine_no) from wines),'[]'::jsonb),'participants',coalesce((select jsonb_agg(jsonb_build_object('name',name,'guesses',guesses,'favorite',favorite) order by name) from participants),'[]'::jsonb)) into r; return r; end $$;
grant select on public.event_settings to anon,authenticated; grant insert,update on public.participants to anon,authenticated; grant select,delete on public.participants to authenticated; grant select,update on public.wines to authenticated; grant update on public.event_settings to authenticated; grant execute on function public.get_results() to anon,authenticated;
